// Block (composition) — a ready-to-use contact form.
// Arranges only; composes Form/TextField/Textarea/Button/Alert/Stack.
import type { FormEvent, Ref } from "react";
import { Form } from "../components/Form";
import { TextField } from "../components/TextField";
import { Textarea } from "../components/Textarea";
import { Button } from "../components/Button";
import { Alert } from "../components/Alert";
import { Stack } from "../layouts/Stack";
import "./ContactForm.css";

export interface ContactFormProps {
  /** Heading shown above the contact fields. */
  heading?: string;
  /** Called with the submitted message. */
  onSubmit?: (data: Record<string, string>) => void;
  /** Form-level error, shown above the fields. */
  errorMessage?: string;
  /** Puts the submit button in a pending state and blocks re-submit. */
  isPending?: boolean;
  className?: string;
  ref?: Ref<HTMLFormElement>;
}

export function ContactForm({
  heading = "Contact us",
  onSubmit,
  errorMessage,
  isPending,
  className,
  ref,
}: ContactFormProps) {
  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    onSubmit?.({
      name: String(data.get("name") ?? ""),
      email: String(data.get("email") ?? ""),
      message: String(data.get("message") ?? ""),
    });
  };

  return (
    <Form isPending={isPending}
      ref={ref}
      onSubmit={handleSubmit}
      className={className ? `sd-contactform ${className}` : "sd-contactform"}
    >
      <Stack gap="large" className="sd-contactform__content">
        {heading && (
          <>
            <h1 className="sd-contactform__heading sd-type-headline-medium">{heading}</h1>
          </>
        )}
        {/* live="assertive": see `AlertProps.live` — submit failure is the case that earns it. */}
        {errorMessage && (
          <Alert variant="error" live="assertive">
            {errorMessage}
          </Alert>
        )}
        <Stack gap="medium" className="sd-contactform__fields">
          <TextField label="Name" name="name" autoComplete="name" isRequired />
          <TextField label="Email" name="email" type="email" autoComplete="email" isRequired />
          <Textarea label="Message" name="message" rows={6} isRequired />
        </Stack>
        <Button size="large" type="submit" variant="primary" isPending={isPending}>
          Send
        </Button>
      </Stack>
    </Form>
  );
}

/* ContactForm.css — arrangement only; Component look stays with its owners. */
/* Fills the column it is given. The page narrows that column on the grid (a Container span), so the
   form's edges land on column lines; a px measure here would leave them off the grid. */
.sd-contactform {
  width: 100%;
}

.sd-contactform__heading {
  margin: 0;
}
